insert into public.entries (id,type,name,summary,body,tags,data,source) values ($q$spell.tran-bat-mon$q$,$q$spell$q$,$q$Trận Bát Môn$q$,null,$q$Cắm 4 lá bùa ở bốn góc, dây chéo chia thành tám cửa. Bán kính 30ft, giữ 1 giờ. Người lập phải đứng trong trận. Mỗi lượt dùng một action để mở một cửa lên một mục tiêu trong trận. Tám cửa: Khai: Gỡ một bùa, phép hoặc lời nguyền; Hưu: Lần chí mạng kế tiếp nhắm vào đồng đội (kể cả bắt vía) thành đòn thường; Sinh: Hồi 1d6 + thông thạo máu, mỗi người một lần mỗi trận; Thương: 1d8 Dương, đẩy lùi 10ft; Đỗ: Một đồng đội vô hình với vong đến lượt sau của người lập; Cảnh: Đọc ý nghĩ bề mặt, hoặc lấy một manh mối từ vong; Tử: Đòn kế tiếp của đồng đội lên vong ăn cả sát thương Ngũ Hành; Kinh: Kẻ địch thắng Tuệ, thua thì đòn kế tiếp của nó bị nghịch.$q$,array[$q$Trấn$q$,$q$Âm$q$,$q$Khế$q$,$q$Cao$q$]::text[],$q${"bac": "Cao", "tinh": ["Trấn", "Âm", "Khế"], "gia": 4, "thi": "Action mở một cửa mỗi lượt · bán kính 30ft · 1 giờ", "hanh_dong": "Action mở một cửa mỗi lượt", "duy_tri": false, "goc": null, "muc": "12.4", "nhap": false, "cua": [{"cua": "Khai", "mo": "Gỡ một bùa, phép hoặc lời nguyền"}, {"cua": "Hưu", "mo": "Lần chí mạng kế tiếp nhắm vào đồng đội (kể cả bắt vía) thành đòn thường"}, {"cua": "Sinh", "mo": "Hồi 1d6 + thông thạo máu, mỗi người một lần mỗi trận"}, {"cua": "Thương", "mo": "1d8 Dương, đẩy lùi 10ft"}, {"cua": "Đỗ", "mo": "Một đồng đội vô hình với vong đến lượt sau của người lập"}, {"cua": "Cảnh", "mo": "Đọc ý nghĩ bề mặt, hoặc lấy một manh mối từ vong"}, {"cua": "Tử", "mo": "Đòn kế tiếp của đồng đội lên vong ăn cả sát thương Ngũ Hành"}, {"cua": "Kinh", "mo": "Kẻ địch thắng Tuệ, thua thì đòn kế tiếp của nó bị nghịch"}], "ghi_chu": "Trận Bát Môn cần 3 tính theo luật bậc Cao. Tui tạm thêm Khế làm tính thứ ba; bạn đổi được."}$q$::jsonb,$q$Bản tổng hợp 21/11 (nháp)$q$) on conflict (id) do update set name=excluded.name,summary=excluded.summary,body=excluded.body,tags=excluded.tags,data=excluded.data,source=excluded.source;
