insert into public.entries (id,type,name,summary,body,tags,data,source) values ($q$rite.van-linh$q$,$q$rite$q$,$q$Vấn Linh$q$,null,$q$Khấn một thần hoặc ma rồi xin keo. Thánh keo: hỏi 3 câu. Tiếu keo: hỏi 1 câu. Âm keo: kẻ khác giả danh trả lời. Thần trả lời thật nhưng ngắn. Ma trả lời đủ nhưng có thể dối, và đòi Uế +1 hoặc một lời hứa$q$,array[$q$Nhập$q$,$q$Hương$q$,$q$nghi lễ$q$]::text[],$q${"tinh": ["Nhập", "Hương"], "thoi_gian": "10 phút, mỗi nghỉ dài một lần", "muc": "12.5"}$q$::jsonb,$q$Bản tổng hợp 21/11$q$) on conflict (id) do update set name=excluded.name,summary=excluded.summary,body=excluded.body,tags=excluded.tags,data=excluded.data,source=excluded.source;
